pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }
    function testFuzz_property(uint256 blockNumber, uint256 ts, address actor) public {
        blockNumber = bound(blockNumber, 1, 10_000_000);
        ts = bound(ts, 1, type(uint256).max / 2);
        vm.roll(blockNumber);
        vm.warp(ts);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok,) = address(c).call{value: 10 ether}("");
        assertTrue(ok);
        // Rule: valid call drains c iff block.number % 15 == 0
        assertTrue((address(c).balance == 0) == (blockNumber % 15 == 0));
    }
}
